//! HF-oracle accuracy gates for the GLM5.2 bricks.
//!
//! Each gate replays a seeded input (generated by `tools/accuracy/glm52_oracle.py`
//! against the pinned transformers `glm_moe_dsa` modeling code) through the
//! engine and asserts the outputs land on hardcoded probe constants within an
//! RMS-scaled tolerance. All gates are `#[ignore]` — they require GPU +
//! checkpoint (EP gates use the SM100 DeepGEMM chain).
//!
//! Run any gate:
//! ```text
//! PEGAINFER_TEST_MODEL_PATH=/data/models/GLM-5.2-FP8 \
//!   cargo test --release -p pegainfer-glm52 --features glm52 --lib mla_oracle -- --ignored --nocapture
//! ```

// The probe constants are pasted verbatim from the harness output; reformatting
// them for these lints would churn on every regeneration.
#![allow(clippy::unreadable_literal, clippy::excessive_precision)]

mod bookend;
mod freerun_ep4;
mod freerun_step;
mod indexer;
mod layer;
mod layer_ep4;
mod mla;
mod mtp_production;
